#!/usr/bin/env bash
# The Cobertura report of global/scripts/languages/golang/test/run.sh, and the
# GO_COVERAGE_IGNORE_GENERATED variable that leaves generated files out of it.
#
# Every repository's report must stay as it was unless the repository asks, so the
# default is pinned as hard as the opt-in. So is what the opt-in must not touch:
# coverage.txt, which the summary, the coverage gate and SonarQube read.
#
# Every case drives the real run.sh over a real module, so the test cannot drift
# away from the script or from the flag gocover-cobertura actually takes.
set -u

SCRIPT_DIR="$(cd "$(dirname "$0")/../.." && pwd)"
RUN_SH="$SCRIPT_DIR/global/scripts/languages/golang/test/run.sh"
EXIT_CODE=0
PASSED=0

echo "[test-go-coverage-report] testing the Cobertura report..." >&2

if [ ! -f "$RUN_SH" ]; then
    echo "[test-go-coverage-report] FAIL: runner not found at $RUN_SH" >&2
    exit 1
fi

if ! command -v go > /dev/null 2>&1; then
    echo "[test-go-coverage-report] SKIP: go is not on PATH." >&2
    exit 0
fi

SANDBOX="$(mktemp -d)" || exit 1
trap 'rm -rf "$SANDBOX"' EXIT

pass() { PASSED=$((PASSED + 1)); echo "[test-go-coverage-report] PASS: $1" >&2; }
fail() { EXIT_CODE=1; echo "[test-go-coverage-report] FAIL: $1" >&2; }

check() {
    local description="$1" actual="$2" expected="$3"

    if [ "$actual" = "$expected" ]; then
        pass "$description"
    else
        fail "$description"
        echo "    expected: [$expected]" >&2
        echo "    actual:   [$actual]" >&2
    fi
}

MODULE="$SANDBOX/module"
mkdir -p "$MODULE/internal/app" "$MODULE/internal/parser"
cat > "$MODULE/go.mod" << 'FIXTURE'
module example.com/report

go 1.25
FIXTURE
cat > "$MODULE/internal/parser/parser.go" << 'FIXTURE'
// Code generated by the fixture. DO NOT EDIT.

package parser

func Parse() int { return 7 }
FIXTURE
cat > "$MODULE/internal/app/app.go" << 'FIXTURE'
package app

import "example.com/report/internal/parser"

func Answer() int { return parser.Parse() }
FIXTURE
cat > "$MODULE/internal/app/app_test.go" << 'FIXTURE'
package app

import "testing"

func TestAnswer(t *testing.T) {
	if Answer() != 7 {
		t.Fatal("unexpected value")
	}
}
FIXTURE

# Runs the real runner and leaves its artefacts in the module. A case with no
# second argument leaves the variable unset, which is every consumer that did not
# opt in.
run_report() { # run_report <case> [GO_COVERAGE_IGNORE_GENERATED]
    local log="$SANDBOX/$1.log"

    rm -f "$MODULE/cobertura.xml" "$MODULE/coverage.txt"
    if [ "$#" -gt 1 ]; then
        (cd "$MODULE" && GO_COVERAGE_IGNORE_GENERATED="$2" "$RUN_SH") > "$log" 2>&1
    else
        (cd "$MODULE" && env -u GO_COVERAGE_IGNORE_GENERATED "$RUN_SH") > "$log" 2>&1
    fi
    local status=$?
    if [ "$status" -ne 0 ]; then
        fail "the runner exited $status on the $1 case"
        tail -20 "$log" >&2
    fi
}

mentions() { # mentions <file> <text>
    grep -cF "$2" "$MODULE/$1"
}

echo "== generated files stay in the report unless a repository asks ==" >&2

run_report default
check "the report keeps a generated file by default" \
    "$(mentions cobertura.xml 'internal/parser/parser.go')" "1"
check "the report keeps a written file by default" \
    "$(mentions cobertura.xml 'internal/app/app.go')" "1"

run_report off false
check "false keeps a generated file in the report" \
    "$(mentions cobertura.xml 'internal/parser/parser.go')" "1"

echo "== GO_COVERAGE_IGNORE_GENERATED leaves them out of the report alone ==" >&2

run_report opted true
check "true leaves a generated file out of the report" \
    "$(mentions cobertura.xml 'internal/parser/parser.go')" "0"
check "true keeps a written file in the report" \
    "$(mentions cobertura.xml 'internal/app/app.go')" "1"
check "true leaves coverage.txt whole, which the gate and SonarQube read" \
    "$(grep -c 'internal/parser/parser.go' "$MODULE/coverage.txt")" "1"
check "true says what it left out" \
    "$(grep -c 'Leaving generated files out of cobertura.xml' "$SANDBOX/opted.log")" "1"

# Azure DevOps stringifies a `boolean` template parameter as `True`.
run_report azure True
check "True, Azure's spelling of a boolean, opts in too" \
    "$(mentions cobertura.xml 'internal/parser/parser.go')" "0"

# ── the GitHub path carries it as an input ────────────────────────────────────
# A reusable workflow receives only `inputs` and `secrets`, so a caller's `env:`
# never reaches run.sh, and a dropped forward would fail nothing: the consumer
# would quietly keep a report it had opted out of.
echo "== the GitHub path threads coverage_ignore_generated into the runner ==" >&2

ACTION="$SCRIPT_DIR/github/golang/stages/30-tests/all/action.yaml"
# shellcheck disable=SC2016  # the single-quoted `${{ }}` is the action's expected TEXT, never an expansion
check "the test action maps the input onto GO_COVERAGE_IGNORE_GENERATED" \
    "$(grep -cF 'GO_COVERAGE_IGNORE_GENERATED: "${{ inputs.coverage_ignore_generated }}"' "$ACTION")" "1"
check "the test action keeps the opt-in off by default" \
    "$(grep -A9 '^  coverage_ignore_generated:$' "$ACTION" | grep -c "default: 'false'")" "1"
for workflow in go go-docker go-flyio go-render; do
    file="$SCRIPT_DIR/.github/workflows/$workflow.yaml"
    check "$workflow.yaml declares coverage_ignore_generated" \
        "$(grep -c '^      coverage_ignore_generated:$' "$file")" "1"
    check "$workflow.yaml keeps it off by default" \
        "$(grep -A3 '^      coverage_ignore_generated:$' "$file" | grep -c 'default: false')" "1"
    check "$workflow.yaml forwards coverage_ignore_generated" \
        "$(grep -cE '^ +coverage_ignore_generated: "?\$\{\{ inputs\.coverage_ignore_generated \}\}"?$' "$file")" "1"
done

if [ "$EXIT_CODE" -eq 0 ]; then
    echo "[test-go-coverage-report] all $PASSED checks passed" >&2
fi
exit "$EXIT_CODE"
